import boto3
from typing import List, Dict, Any
from safety_client import get_aws_client
from safety_models import BatchTextModerationRequest, TextModerationResult

def moderate_batch(payload: BatchTextModerationRequest, config: Dict[str, Any] = None) -> List[TextModerationResult]:
    config = config or {}
    client = get_aws_client("comprehend", config)

    text_segments = [{
        "Text": text
    } for text in payload.texts]

    response = client.detect_toxic_content(
        TextSegments=text_segments,
        LanguageCode=payload.language_code
    )

    results = []
    for i, result in enumerate(response["ResultList"]):
        results.append(TextModerationResult(
            text=payload.texts[i],
            is_safe=result["Toxicity"]["Value"] < config.get("toxicity_threshold", 0.5), # Placeholder for safety decision
            scores=result["Toxicity"],
            categories=result["Categories"]
        ))
    return results

from typing import Dict, Any, List
from safety_models import TextModerationResult, ModerationDecision

def safety_threshold(moderation_result: TextModerationResult, thresholds: Dict[str, float]) -> ModerationDecision:
    reasons = []
    allowed = True

    # Example: Apply thresholds based on category scores
    for category in moderation_result.categories:
        name = category["Name"]
        score = category["Score"]

        if name in thresholds and score > thresholds[name]:
            allowed = False
            reasons.append(f"Category '{name}' exceeded threshold with score {score:.2f} (threshold: {thresholds[name]:.2f})")

    # Apply overall toxicity threshold if present in scores
    if "Toxicity" in moderation_result.scores:
        toxicity_score = moderation_result.scores["Toxicity"]["Value"]
        if "overall_toxicity" in thresholds and toxicity_score > thresholds["overall_toxicity"]:
            allowed = False
            reasons.append(f"Overall toxicity exceeded threshold with score {toxicity_score:.2f} (threshold: {thresholds["overall_toxicity"]:.2f})")

    return ModerationDecision(
        text=moderation_result.text,
        allowed=allowed,
        reasons=reasons
    )

import boto3
from typing import Dict, Any
from safety_client import get_aws_client
from safety_models import TranslationRequest, TranslationResult

def appeal_translate(payload: TranslationRequest, config: Dict[str, Any] = None) -> TranslationResult:
    config = config or {}
    client = get_aws_client("translate", config)

    response = client.translate_text(
        Text=payload.text_to_translate,
        SourceLanguageCode=payload.source_language,
        TargetLanguageCode=payload.target_language
    )

    return TranslationResult(translated_text=response["TranslatedText"])
